const $ = QF.dom.$, on = QF.dom.on;
const reply = await QF.editor.getData();
if (!reply.ok) throw new Error(reply.error.message);
let question = reply.data;
QF.layout.configure({ cardWidth: 720, maxCardWidth: '100%', horizontalAlign: 'center', verticalAlign: 'top', padding: 20 });
QF.ui.configure({ title: false, save: false, position: false, typeLabel: false, add: false, duplicate: false, delete: false, sources: false });
$('[data-type-title]').textContent = '判断题编辑';
let actionBusy = false;
async function shellState() {
  const response = await QF.bank.getState(), available = response.ok;
  $('[data-bank-save]').hidden = !available; $('[data-bank-actions]').hidden = !available; $('[data-source-section]').hidden = !available;
  if (!available) return;
  const state = response.data;
  $('[data-bank-position]').textContent = `第 ${state.index + 1} / ${state.count} 题`;
  const select = $('[data-bank-add]'); select.replaceChildren(new Option('＋ 新增题目', ''));
  state.types.forEach(type => select.append(new Option(type.label, type.id)));
  const rows = $('[data-sources]'); rows.replaceChildren();
  state.sources.forEach((source, index) => {
    const row = document.createElement('div'); row.className = 'qf-type-source';
    const open = document.createElement('button'); open.type = 'button'; open.textContent = source.label; open.disabled = actionBusy || !source.navigable; open.title = source.message; open.dataset.sourceAction = 'open'; open.dataset.sourceIndex = index;
    const message = document.createElement('span'); message.className = 'muted'; message.textContent = source.message;
    const remove = document.createElement('button'); remove.type = 'button'; remove.textContent = '移除'; remove.setAttribute('aria-label', '移除来源 ' + source.label); remove.dataset.sourceAction = 'remove'; remove.dataset.sourceIndex = index; remove.disabled = actionBusy;
    row.append(open, message, remove); rows.append(row);
  });
  for (const selector of ['[data-bank-save]', '[data-bank-add]', '[data-bank-duplicate]', '[data-bank-delete]', '[data-delete-accept]', '[data-source-add]']) $(selector).disabled = actionBusy;
}
async function runAction(action) {
  if (actionBusy) return; actionBusy = true;
  try { await shellState(); const response = await action(); if (!response.ok) QF.ui.notify(response.error.message); return response; }
  finally { actionBusy = false; await shellState(); }
}
on($('[data-bank-save]'), 'click', () => runAction(() => QF.bank.save()));
on($('[data-bank-add]'), 'change', () => { const type = $('[data-bank-add]').value; if (type) return runAction(() => QF.bank.addQuestion(type)); });
on($('[data-bank-duplicate]'), 'click', () => runAction(() => QF.bank.duplicateQuestion()));
on($('[data-bank-delete]'), 'click', () => { $('[data-delete-confirm]').hidden = false; });
on($('[data-delete-cancel]'), 'click', () => { $('[data-delete-confirm]').hidden = true; });
on($('[data-delete-accept]'), 'click', () => runAction(() => QF.bank.deleteQuestion()));
async function addSource() {
  const link = $('[data-source-link]').value;
  const response = await runAction(() => QF.sources.add(link));
  if (response?.ok) $('[data-source-link]').value = '';
}
on($('[data-source-add]'), 'click', addSource);
on($('[data-sources]'), 'click', event => { const button = event.target.closest('[data-source-action]'); if (button && !button.disabled) return runAction(() => button.dataset.sourceAction === 'open' ? QF.sources.open(Number(button.dataset.sourceIndex)) : QF.sources.remove(Number(button.dataset.sourceIndex))); });
on($('[data-source-link]'), 'keydown', event => { if (event.key === 'Enter') { event.preventDefault(); return addSource(); } });
QF.host.subscribe(shellState); await shellState();
async function update(patch) {
  const response = await QF.editor.update(patch);
  if (!response.ok) { QF.ui.notify(response.error.message); return; }
  question = response.data;
}
$('[data-prompt]').value = question.prompt.text;
on($('[data-prompt]'), 'input', () => update({ prompt: { kind: 'TEXT', text: $('[data-prompt]').value } }));
$('[data-score]').value = question.scoreSpec.defaultMaxScore;
on($('[data-score]'), 'input', () => update({ scoreSpec: { defaultMaxScore: Number($('[data-score]').value) } }));
// Options are fixed; IDs come from question data and may change on duplication.
const answers = [$('[data-correct-true]'), $('[data-correct-false]')];
function refreshAnswer() {
  answers.forEach((input, index) => {
    input.checked = question.answerSpec.correctOptionIds.includes(question.payload.options[index].id);
    input.closest('label').classList.toggle('selected', input.checked);
  });
}
answers.forEach((input, index) => on(input, 'change', async () => {
  const response = await QF.editor.update({ answerSpec: { kind: 'CHOICE', correctOptionIds: [question.payload.options[index].id] } });
  if (response.ok) question = response.data; else QF.ui.notify(response.error.message);
  refreshAnswer();
}));
refreshAnswer();
QF.content.mountEditor($('[data-analysis]'), { value: question.analysis, formatting: true, onChange: analysis => update({ analysis }) });

assets.rendererSource:
const $ = QF.dom.$, on = QF.dom.on;
const reply = await QF.practice.getQuestion(); if (!reply.ok) throw new Error(reply.error.message);
const question = reply.data;
QF.layout.configure({ cardWidth: 720, maxCardWidth: '100%', horizontalAlign: 'center', verticalAlign: 'center', padding: 20 });
QF.ui.configure({ typeLabel: false, position: false, score: false, state: false, submit: false, retry: false, confirmation: false, note: false, sources: false, draftToggle: true, draftToolbar: true, draftZoom: true });
let confirming = false, actionBusy = false;
$('[data-type-label]').textContent = '判断题';
$('[data-choice-hint]').textContent = '请选择这句话的判断结果';
async function runAction(action) {
  if (actionBusy) return; actionBusy = true;
  try { await refresh(); const response = await action(); if (!response.ok) QF.ui.notify(response.error.message); return response; }
  finally { actionBusy = false; await refresh(); }
}
on($('[data-submit-answer]'), 'click', () => { confirming = true; $('[data-answer-confirm]').hidden = false; refresh().then(() => $('[data-confirm-answer]').focus()); });
on($('[data-cancel-answer]'), 'click', () => { confirming = false; refresh(); });
on($('[data-confirm-answer]'), 'click', () => { confirming = false; return runAction(() => QF.practice.submit()); });
on($('[data-retry-answer]'), 'click', () => runAction(() => QF.practice.retry()));
on($('[data-sources]'), 'click', event => { const button = event.target.closest('[data-source-index]'); if (button && !button.disabled) return runAction(() => QF.sources.open(Number(button.dataset.sourceIndex))); });
$('[data-prompt]').textContent = question.prompt.text;
const controls = [$('[data-answer-true]'), $('[data-answer-false]')].map((input, index) => {
  const option = question.payload.options[index], row = input.closest('label');
  input.value = option.id; input.setAttribute('aria-label', option.content.text);
  on(input, 'change', async () => {
    const response = await QF.answer.update({ selectedOptionIds: [option.id] });
    if (!response.ok) QF.ui.notify(response.error.message);
    await refresh();
  });
  return { option, input, row, feedback: row.querySelector('.qf-option-feedback') };
});
async function refresh() {
  const [a, c, r, s, n] = await Promise.all([QF.answer.get(), QF.host.getContext(), QF.practice.getResult(), QF.practice.getState(), QF.navigation.getState()]);
  if (!a.ok || !c.ok || !r.ok || !s.ok) return;
  const selected = new Set(a.data.selectedOptionIds || []), result = r.data;
  const capabilities = c.data.capabilities, state = s.data;
  $('[data-question-position]').textContent = Number.isInteger(state.index) ? `第 ${state.index + 1} / ${state.total} 题` : '';
  $('[data-max-score]').textContent = `分值：${state.maxScore ?? '未设置'}`;
  $('[data-answer-state]').textContent = ({ UNANSWERED: '未作答', DRAFT: '已选择', SUBMITTED: '已提交', RETRYING: '重试中', REVISING: '修订中' })[state.state] || '';
  $('[data-answer-confirm]').hidden = !confirming;
  $('[data-submit-answer]').hidden = c.data.mode === 'HISTORY' || c.data.mode === 'PREVIEW' || !capabilities.submit || Boolean(result);
  $('[data-submit-answer]').disabled = actionBusy || confirming || !capabilities.submit || selected.size === 0;
  $('[data-retry-answer]').hidden = c.data.mode === 'HISTORY' || c.data.mode === 'PREVIEW' || !capabilities.retry || !result;
  $('[data-retry-answer]').disabled = actionBusy || !capabilities.retry;
  $('[data-confirm-answer]').disabled = actionBusy;
  const sourceRows = $('[data-sources]'); sourceRows.replaceChildren();
  const sources = n.ok ? n.data.sources : []; $('[data-source-section]').hidden = !sources.length;
  sources.forEach((source, index) => {
    const row = document.createElement('div'); row.className = 'qf-type-source'; const button = document.createElement('button'); button.type = 'button'; button.textContent = source.label; button.disabled = actionBusy || !source.navigable; button.dataset.sourceIndex = index;
    const message = document.createElement('span'); message.className = 'muted'; message.textContent = source.message; row.append(button, message); sourceRows.append(row);
  });
  $('[data-stage-note]').textContent = c.data.mode === 'HISTORY' ? '历史草稿 · 只读' : c.data.mode === 'PREVIEW' ? '只读预览' : '草稿自动保存；提交后冻结，重试从空白草稿开始。';
  const correct = result?.reference?.answerSpec?.correctOptionIds || result?.correctOptionIds || [];
  for (const { option, input, row, feedback } of controls) {
    input.checked = selected.has(option.id); input.disabled = actionBusy || confirming || !capabilities.editAnswer;
    row.classList.toggle('selected', input.checked);
    row.classList.toggle('correct', Boolean(result) && correct.includes(option.id));
    row.classList.toggle('incorrect', Boolean(result) && input.checked && !correct.includes(option.id));
    feedback.hidden = !result || (!input.checked && !correct.includes(option.id));
    feedback.textContent = correct.includes(option.id) ? (input.checked ? '正确 · 已选' : '正确答案') : '你的答案';
  }
  $('[data-result]').hidden = !result;
  if (result) {
    $('[data-verdict]').textContent = result.status === 'CORRECT' ? '回答正确' : result.status === 'INCORRECT' ? '回答错误' : '未评分';
    $('[data-verdict]').className = result.status === 'CORRECT' ? 'correct' : 'incorrect';
    $('[data-score]').textContent = '得分：' + (result.score ?? '未评分') + ' / ' + result.maxScore;
    $('[data-correct-answer]').textContent = '正确答案：' + question.payload.options.map(o => correct.includes(o.id) ? o.content.text : null).filter(Boolean).join('、');
    QF.content.render($('[data-analysis]'), result.reference?.analysis || result.analysis || { kind: 'TEXT', text: '' });
  }
}
QF.host.subscribe(refresh); await refresh();

assets.rulesSource:
QF.defineQuestionType({
  type: 'TRUE_FALSE',
  validate(question) {
    const errors = [];
    if (question.prompt?.kind !== 'TEXT' || typeof question.prompt.text !== 'string' || !question.prompt.text.trim()) {
      errors.push('请填写普通文本题干');
    }
    const options = question.payload?.options;
    const validOptions = question.payload?.kind === 'CHOICE' && Array.isArray(options) && options.length === 2
      && options.every((option, index) => typeof option?.id === 'string' && option.id.startsWith('opt_')
        && option.content?.kind === 'TEXT' && option.content.text === ['正确', '错误'][index])
      && options[0].id !== options[1].id;
    if (!validOptions) errors.push('判断题需按顺序保留正确、错误两个固定选项和独立选项标识');
    const correct = question.answerSpec?.correctOptionIds;
    if (question.answerSpec?.kind !== 'CHOICE' || !Array.isArray(correct) || correct.length !== 1
      || !validOptions || !options.some(option => option.id === correct[0])) errors.push('请选择有效的正确答案');
    if (!Number.isFinite(question.scoreSpec?.defaultMaxScore) || question.scoreSpec.defaultMaxScore <= 0) {
      errors.push('分值必须为正数');
    }
    return errors;
  },
  validateAnswer(question, answer) {
    const selected = answer.selectedOptionIds;
    const valid = Array.isArray(selected) && selected.length <= 1
      && selected.every(id => question.payload.options.some(option => option.id === id));
    return { empty: valid && selected.length === 0, errors: valid ? [] : ['请选择正确或错误中的一个选项'] };
  },
  grade({ question, answer, maxScore, reportResult }) {
    const selected = answer.selectedOptionIds || [];
    const right = selected.length === 1 && selected[0] === question.answerSpec.correctOptionIds[0];
    return reportResult({ score: right ? maxScore : 0 });
  }
});

